SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsOnHandRequest
{
    DataAreaId       dataAreaId;
    ItemId           itemId;
    InventLocationId warehouseId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('ItemId')]
public ItemId parmItemId(ItemId _value = itemId)
{
    itemId = _value;
    return itemId;
}

/// <summary>
/// Optional. Blank means every warehouse, which is what the enquiry screen's toggle sends.
/// </summary>
[DataMemberAttribute('WarehouseId')]
public InventLocationId parmWarehouseId(InventLocationId _value = warehouseId)
{
    warehouseId = _value;
    return warehouseId;
}
